    def create_resource_widget(self):
        """创建CPU/内存显示控件，并添加到状态栏最右侧"""
        # 1. 创建资源显示容器
        self.resource_widget = QtWidgets.QWidget(self.statusbar)  # 父对象绑定到状态栏
        self.resource_layout = QtWidgets.QHBoxLayout(self.resource_widget)
        self.resource_layout.setContentsMargins(0, 5, 0, 5)  # 适配状态栏边距
        self.resource_layout.setSpacing(10)  # 两个标签间距
        self.resource_layout.setAlignment(Qt.AlignCenter)

        # 2. CPU标签
        self.cpu_label = QtWidgets.QLabel(self.resource_widget)
        self.cpu_label.setObjectName("cpuLabel")
        self.cpu_label.setStyleSheet("""
            font-family: Microsoft YaHei;
            font-size: 14px;
            color: #979797;
            padding: 2px 10px;
        """)

        # 3. 内存标签
        self.mem_label = QtWidgets.QLabel(self.resource_widget)
        self.mem_label.setObjectName("memLabel")
        self.mem_label.setStyleSheet("""
            font-family: Microsoft YaHei;
            font-size: 14px;
            color: #979797;
            padding: 2px 10px;
        """)

        # 4. 添加标签到布局
        self.resource_layout.addWidget(self.cpu_label)
        self.resource_layout.addWidget(self.mem_label)

        # 5. 关键：将控件添加到状态栏【最右侧】且永久显示
        # addPermanentWidget 特性：固定在状态栏最右侧，不会被临时消息覆盖
        self.statusbar.addPermanentWidget(self.resource_widget)

    def update_resource_usage(self):
        """每秒更新CPU/内存使用率"""
        try:
            cpu_usage = psutil.cpu_percent(interval=0.1)  # 缩短采样间隔，避免卡顿
            mem_usage = psutil.virtual_memory().percent
            self.cpu_label.setText(f"CPU: {cpu_usage:.1f}%")
            self.mem_label.setText(f"Memory: {mem_usage:.1f}%")
        except Exception as e:
            self.cpu_label.setText("CPU: --")
            self.mem_label.setText("Memory: --")
            print(f"获取资源失败: {e}")

    def on_remind(self, msg: str, seconds_left: int):
        QMessageBox.warning(self.window, "许可到期提醒", msg)
        # 到期：禁用 Preprocess、Analysis module、File 下的 Open/Close
        if seconds_left <= 0:
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
            self.action_open_edf_files.setEnabled(False)
            self.action_close_file.setEnabled(False)

