    def open_data_tran(self):
        try:
            options = QFileDialog.Options()
            path = QFileDialog.getExistingDirectory(None, "Select Directory", options=options)
            if path:
                for file in os.listdir(path):
                    if file.endswith(('.edf', '.bdf')):
                        file_path = os.path.join(path, file)
                        if not self.check_file_size(file_path):
                            return  # 若有超大文件，终止处理
                from .process_path import process_path
                QLLogging.log.debug("enter process_path")
                process_path(path)
                QLLogging.log.debug("process_path successfully")
                last_foler_name = os.path.basename(path)
                edf_path = os.path.join(path, f"{last_foler_name}.edf")
                QLLogging.log.debug("enter showInfo")
                self.showInfo(edf_path)
                QLLogging.log.debug("showInfo successfully")

                base_path = os.path.dirname(edf_path)
                result_path = os.path.join(base_path, 'Result')
                from datetime import datetime
                folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
                folder_path = os.path.join(result_path, folder_name)
                self.updateDescription(folder_path)
        except Exception as e:
            QLLogging.log.exception(f"open_data_tran error: {e}")

