    def check_user_config(self, file_path):
        import psutil
        # 获取内存信息
        memory = psutil.virtual_memory()
        total_memory = round(memory.total / (1024 ** 3), 2)

        # 检查是否已经显示过提示
        if not self.ifconfigremind:
            return

        try:
            file_size = os.path.getsize(file_path)  # 获取文件大小（字节）
            max_size_mb_24h = 600
            max_size_bytes_24h = max_size_mb_24h * 1024 * 1024  # 转换为字节
            max_size_mb_12h = 300
            max_size_bytes_12h = max_size_mb_12h * 1024 * 1024  # 转换为字节

            is_below_spec = False

            # 判断是否低于推荐配置
            if file_size <= max_size_bytes_12h:
                if total_memory < 30:  # 一般32G内存电脑实际31.9GB
                    is_below_spec = True
            elif max_size_bytes_12h < file_size <= max_size_bytes_24h:
                if total_memory < 60:
                    is_below_spec = True

            if is_below_spec:
                # 创建顶部提示栏
                self.create_config_warning_bar(file_size, total_memory)

        except Exception as e:
            QLLogging.log.exception(f"Failed to check user configuration: {e}")

