    def showInfo(self, file_path):
        try:
            # self.textEdit.show()  # 这个页面是一个TextEdit
            self.welcome_widget.welcome_text0.hide()
            self.welcome_widget.welcome_widget_old.hide()
            self.welcome_widget.welcome_text1.hide()
            self.welcome_widget.bottom_label.hide()
            self.showFileWidgetShow()
            self.show_file_ScrollArea.show()

            file_extension = os.path.splitext(file_path)[1].lower()
            QLLogging.log.debug("enter EdfReader")
            edf_r = EdfReader(file_path)
            QLLogging.log.debug("EdfReader successfully")
            start_time = edf_r.getStartdatetime()
            del edf_r

            if file_extension == '.edf':
                QLLogging.log.debug("enter mne.io.read_raw_edf")
                self.raw = mne.io.read_raw_edf(file_path, preload=True, verbose=False)
                QLLogging.log.debug("mne.io.read_raw_edf successfully")
                # self.raw._data = self.raw.get_data().astype('float32') # 将数据转换为float32类型

            elif file_extension == '.bdf':
                QLLogging.log.debug("enter mne.io.read_raw_bdf")
                self.raw = mne.io.read_raw_bdf(file_path, preload=True, verbose=False)
                QLLogging.log.debug("mne.io.read_raw_bdf successfully")

            try:
                raw_sfreq = float(self.raw.info.get('sfreq', 0))
            except Exception:
                raw_sfreq = 0
            QLLogging.log.debug(f"采样率(read_raw): {raw_sfreq:.2f}Hz")

            # 直接将数据转换为微伏（而不是先存储在中间变量中）
            self.raw._data *= 1e6  # 将数据转换为微伏，直接修改self.raw._data

            # 如果你只想保留最终处理后的数据，创建一个新的 RawArray 对象
            QLLogging.log.debug("enter mne.io.RawArray")
            self.raw_processed = mne.io.RawArray(self.raw._data, self.raw.info)
            QLLogging.log.debug("mne.io.RawArray successfully")
            
            # 重要：复制 annotations（事件）到 raw_processed
            # RawArray 创建时不会自动复制 annotations，需要手动复制
            if hasattr(self.raw, 'annotations') and self.raw.annotations is not None:
                try:
                    self.raw_processed.set_annotations(self.raw.annotations)
                    QLLogging.log.info(f"成功复制 annotations 到 raw_processed: {len(self.raw.annotations)} 个事件")
                    # 记录前几个事件的详细信息
                    if len(self.raw.annotations) > 0:
                        for i in range(min(3, len(self.raw.annotations))):
                            QLLogging.log.info(f"  事件 {i+1}: {self.raw.annotations.description[i]} @ {self.raw.annotations.onset[i]}s")
                except Exception as e:
                    QLLogging.log.warning(f"复制 annotations 时出错: {e}")
                    import traceback
                    QLLogging.log.debug(f"复制 annotations 错误详情: {traceback.format_exc()}")
            else:
                QLLogging.log.warning("原始 raw 对象没有 annotations 或 annotations 为 None")

            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_infotext)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext1)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext2)
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext3)

            n_channels = len(self.raw_processed.ch_names)
            n_times = self.raw_processed.n_times
            sfreq = self.raw_processed.info['sfreq']
            QLLogging.log.info(f"采样率: {sfreq:.2f}Hz")
            print(f"采样率: {sfreq:.2f}Hz")
            if sfreq > 1000:
                QMessageBox.warning(self, "提示", f"采样率超过1000Hz（当前{sfreq:.2f}Hz），无法导入该文件。")
                self.raw = None
                self.raw_processed = None
                return
            total_duration = n_times / sfreq
            hms = self.seconds_to_hms(total_duration)

            data = self.raw_processed.get_data()
            file_size = os.path.getsize(file_path)  # 获取文件大小（字节）
            actual_size = round(file_size / (1024 * 1024), 2)

            memory_usage_mb = data.size * data.itemsize / (1024 ** 2)
            memory_usage_mb = round(memory_usage_mb, 2)

            test1 = "数据规格：          " + str(n_channels) + "x" + str(n_times)
            test2 = "数据时长：          " + hms
            test3 = "数据大小：          " + str(actual_size) + "MB"
            test4 = "通道数量：          " + str(n_channels)

            # 添加内容到textEdit中的内容
            ch_name = self.raw_processed.info['ch_names']
            sfreq = self.raw_processed.info['sfreq']
            meas_date = self.raw_processed.info['meas_date']
            try:
                new_ch_name = []

                change_ch_name = False

                for ch in ch_name:
                    if ch in self.ch_name_mapping:
                        change_ch_name = True
                        new_ch_name.append(self.ch_name_mapping[ch])
                # 需要有一个条件
                if change_ch_name:
                    ch_name = new_ch_name

                    # 假设 self.raw_processed 是 MNE 的 Raw 对象，ch_name 是新通道名称列表
                    # 构建原通道名和新通道名的映射字典
                    name_mapping = {old_name: new_name for old_name, new_name in
                                    zip(self.raw_processed.ch_names, ch_name)}
                    # 执行重命名
                    self.raw_processed.rename_channels(name_mapping)
            except Exception as e:
                QLLogging.log.exception(f"{e}")

            test5 = "通道名称：          " + str(ch_name)
            test6 = "采样率：            " + str(sfreq) + "Hz"
            test7 = "文件路径：          " + str(file_path)
            test8 = "记录开始时间：   " + str(meas_date) 
            self.ch_name = ch_name
            self.show_file_widget.show_file_infotext.append(test1)
            self.show_file_widget.show_file_infotext.append(test2)
            self.show_file_widget.show_file_infotext.append(test3)
            self.show_file_widget.show_file_infotext.append(test4)
            self.show_file_widget.show_file_infotext.append(test5)
            self.show_file_widget.show_file_infotext.append(test6)
            self.show_file_widget.show_file_infotext.append(test7)
            self.show_file_widget.show_file_infotext.append(test8)

            self.show_file_widget.show_file_disposetext1.append("【Filter】")
            for ch in ch_name:
                self.show_file_widget.show_file_disposetext1.append(f"# Filter({ch}):   None")

            self.show_file_widget.show_file_disposetext2.append("【data selection】")
            self.show_file_widget.show_file_disposetext2.append("暂无")
            self.show_file_widget.show_file_disposetext3.append("【preview and rejection】")
            self.show_file_widget.show_file_disposetext3.append("暂无")

            # 删除不再需要的原始数据
            del self.raw

            # 成功加载数据后启用菜单和关闭
            self.menuPreprocess.setEnabled(True)
            self.menuAnalysis_module.setEnabled(True)
            self.action_close_file.setEnabled(True)
            self.action_save_file.setEnabled(True)

            # 更鲁棒的 EEG 通道数识别：优先用通道类型，其次用标准10-20名称表（排除ACC）
            eeg_channels = 0
            has_acc_channel = False
            standard_23 = {
                'FP1', 'FP2', 'C3', 'C4', 'O1', 'O2', 'CZ', 'T3', 'T4',
                'F3', 'F4', 'FZ', 'F7', 'F8', 'PZ', 'P3',
                'T5', 'P4', 'T6', 'FPZ', 'OZ', 'M1', 'M2'
            }

            try:
                ch_types = self.raw_processed.get_channel_types()
            except Exception:
                ch_types = []

            for idx, ch in enumerate(self.raw_processed.ch_names):
                ch_upper = str(ch).upper()
                if 'ACC' in ch_upper:
                    has_acc_channel = True
                    continue

                ch_type = ch_types[idx] if idx < len(ch_types) else None
                if ch_type == 'eeg':
                    eeg_channels += 1
                    continue

                if ch_upper.startswith('EEG') or ch_upper in standard_23:
                    eeg_channels += 1

            print("-------------channel", eeg_channels, self.raw_processed.ch_names)

            # 默认：分析入口全部置灰（仅置灰子入口，不禁用总菜单）
            self.actionBasical_analysis.setEnabled(False)
            self.actionEpilepsy_analysis.setEnabled(False)
            self.actionBandPower.setEnabled(False)
            self.actionPSD.setEnabled(False)
            self.actionTimeFrequency.setEnabled(False)
            self.actionActivity.setEnabled(False)
            self.actionECG_analysis.setEnabled(False)
            self.actionEpilepsy_STD.setEnabled(False)
            self.actionEpilepsy_ML.setEnabled(False)
            self.actionEMG_analysis.setEnabled(False)
            self.actionQlass_analysis.setEnabled(False)
            self.actionQEEG_analysis.setEnabled(False)

            # 条件1：EEG通道数=4 且含ACC通道 -> 启用除QEEG外的分析入口
            if eeg_channels == 4 and has_acc_channel:
                self.menuPreprocess.setEnabled(True)
                self.menuAnalysis_module.setEnabled(True)
                self.action_close_file.setEnabled(True)
                self.action_save_file.setEnabled(True)
                self.actionBasical_analysis.setEnabled(True)
                self.actionEpilepsy_analysis.setEnabled(True)
                self.actionBandPower.setEnabled(True)
                self.actionPSD.setEnabled(True)
                self.actionTimeFrequency.setEnabled(True)
                self.actionActivity.setEnabled(True)
                self.actionECG_analysis.setEnabled(True)
                self.actionEpilepsy_STD.setEnabled(True)
                self.actionEpilepsy_ML.setEnabled(True)
                self.actionEMG_analysis.setEnabled(True)
                self.actionQlass_analysis.setEnabled(True)

            # 条件2：EEG通道数=23 -> 仅启用QEEG入口
            elif eeg_channels == 23:
                self.menuPreprocess.setEnabled(False)
                self.action_save_file.setEnabled(False)
                self.menuAnalysis_module.setEnabled(True)
                # 仅启用 QEEG，其他分析入口一律置灰（含带子菜单的 Basical/Epilepsy）
                self.actionBasical_analysis.setEnabled(False)
                self.actionEpilepsy_analysis.setEnabled(False)
                self.actionQEEG_analysis.setEnabled(True)

            else:
                # 既不是 4 通道(含 ACC)也不是 23 通道：分析入口全部置灰
                self.menuPreprocess.setEnabled(False)
                self.menuAnalysis_module.setEnabled(False)


        except Exception as e:
            self.welcome_widget.welcome_text0.show()
            self.welcome_widget.welcome_widget_old.show()
            self.welcome_widget.welcome_text1.show()
            self.welcome_widget.bottom_label.show()
            self.show_file_ScrollArea.hide()
            self.showFileWidgetHide()
            # 创建一个显示错误的弹窗
            msg_box = QMessageBox()
            msg_box.setIcon(QMessageBox.Critical)  # 设置图标为错误图标
            msg_box.setWindowTitle("错误提示")
            msg_box.setText(f"<p style='font-size: 25px;'>Failed to load the file:\n</p> <div>{e}</div>")
            msg_box.exec_()
            QLLogging.log.exception(f"Failed to load the file: {e}")
            # 加载失败时确保菜单保持禁用
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
