    def seconds_to_hms(self, seconds):
        # 计算小时数
        hours = int(seconds // 3600)
        # 计算剩余的秒数用于计算分钟数
        remaining_seconds = seconds % 3600
        # 计算分钟数
        minutes = int(remaining_seconds // 60)
        # 计算最后的秒数
        secs = int(remaining_seconds % 60)
        # 格式化输出为 HH:MM:SS 格式
        return f"{hours:02d}:{minutes:02d}:{secs:02d}"

