    def get_reject_UI_reject_log(self, reject_log):
        import copy
        try:
            # 定义正则表达式模式
            self.show_file_widget.show_file_disposetext3.clear()
            self.show_file_widget.show_file_disposetext3.append("【preview and rejection】")
            ControlStyle._textEdit_word_style(self.show_file_widget.show_file_disposetext3)

            if self.reject_ui.history_reject_time is not None:
                # 先合并数组
                history_reject_time1 = copy.deepcopy(self.history_reject_time)
                history_reject_time1.extend(self.reject_ui.now_reject_time)
                # 再进行判断数量是否大于100，如果大于100，头删至100
                while len(history_reject_time1) > 99:
                    history_reject_time1.popleft()  # 使用deque的popleft替代列表的pop(0)

                for i in range(len(history_reject_time1)):
                    number = i + 1
                    self.show_file_widget.show_file_disposetext3.append(
                        f"reject{number:2d}:\t" + history_reject_time1[i])
        except Exception as e:
            QLLogging.log.exception(f"get_reject_UI_reject_log error: {str(e)}")  # 428

