    def on_bandpower_close(self, event):
        """处理频带分析窗口关闭"""
        try:
            from PyQt5.QtWidgets import QMessageBox, QCheckBox

            if not self.is_force_close:
                # 询问是否关闭 Bandpower Analysis 窗口
                if not self.checkbox_settings_bp.value("confirm_close_bp", True, type=bool):
                    pass
                else:
                    dlg = QMessageBox(self)
                    dlg.setWindowIcon(QIcon("QL1.ico"))
                    dlg.setIcon(QMessageBox.Information)
                    dlg.setWindowTitle("Close Bandpower Analysis")
                    dlg.setText(
                        "Are you sure you want to close the Bandpower analysis window? This will restart analysis.")
                    dlg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
                    dlg.setDefaultButton(QMessageBox.No)
                    cb = QCheckBox("Don't ask again")
                    dlg.setCheckBox(cb)
                    reply = dlg.exec_()
                    if cb.isChecked():
                        self.checkbox_settings_bp.setValue("confirm_close_bp", False)
                    if reply != QMessageBox.Yes:
                        if event:
                            event.ignore()
                        self.ifclose = False
                        return
                    self.ifclose = True
                    self.bandpower_ui = None

            # 清理资源
            if self.bandpower_ui is not None:
                self.bandpower_ui.close()
                self.bandpower_ui = None

            event.accept()

            # 4. 手动触发垃圾回收
            import gc
            gc.collect()
        except Exception as e:
            QLLogging.log.exception(f"Error closing bandpower window: {str(e)}")
            event.accept()

