    def close_qeeg_analysis(self, event=None):
        """关闭qeeg分析窗口并清理所有相关资源"""
        from PyQt5.QtWidgets import QMessageBox, QCheckBox

        # 兼容旧逻辑：若曾因取消关闭而误写成不再询问，则重置一次
        if not self.checkbox_settings_sleep.value("confirm_close_qeeg_migrated", False, type=bool):
            self.checkbox_settings_sleep.setValue("confirm_close_qeeg", True)
            self.checkbox_settings_sleep.setValue("confirm_close_qeeg_migrated", True)

        if not self.is_force_close:
            # 询问是否关闭窗口
            if not self.checkbox_settings_sleep.value("confirm_close_qeeg", True, type=bool):
                pass
            else:
                dlg = QMessageBox(self)
                dlg.setWindowIcon(QIcon("QL1.ico"))
                dlg.setIcon(QMessageBox.Information)
                dlg.setWindowTitle("Close qEEG Analysis")
                dlg.setText("关闭窗口将结束当前程序，并返回到重新开始分析的界面。本次分析结果已保存，可在受试者数据库-历史记录中查看。")
                dlg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
                dlg.setDefaultButton(QMessageBox.No)
                cb = QCheckBox("不再询问")
                dlg.setCheckBox(cb)
                reply = dlg.exec_()
                if reply != QMessageBox.Yes:
                    if event:
                        event.ignore()
                    self.ifclose = False
                    return
                if cb.isChecked():
                    self.checkbox_settings_sleep.setValue("confirm_close_qeeg", False)
                self.qlass_window = None
                self.ifclose = True

        import matplotlib.pyplot as plt
        try:
            QLLogging.log.info("Starting cleanup...")
            if hasattr(self, 'qeeg_ui') and self.qeeg_ui is not None:
                # 先处理线程
                if hasattr(self.qeeg_ui, 'thread_run'):
                    thread = self.qeeg_ui.thread_run
                    if thread.isRunning():
                        thread.terminate()
                        thread.wait()
                    thread.cleanup()  # 调用新的cleanup方法
                    thread.deleteLater()  # 确保线程被正确删除

                # 清理matplotlib资源
                if hasattr(self.qeeg_ui, 'figure'):
                    plt.close(self.qeeg_ui.figure)
                    self.qeeg_ui.figure.clear()
                    del self.qeeg_ui.figure

                if hasattr(self.qeeg_ui, 'canvas'):
                    try:
                        # 检查 canvas 是否仍然有效
                        if hasattr(self.qeeg_ui.canvas, 'close'):
                            self.qeeg_ui.canvas.close()
                    except RuntimeError as e:
                        QLLogging.log.warning(f"Could not close canvas: {e}")
                    finally:
                        del self.qeeg_ui.canvas

                # 清理所有大型数据属性 为修改
                large_data_attrs = [
                    'raw_processed', 'df_score', 'eeg_data', 'emg_data',
                    'acc_data', 'spectrogram_data', 'scores', 'stages',
                    'color_epochs', 'highlight_lines', 'epochlabels'
                ]

                for attr in large_data_attrs:
                    if hasattr(self.qeeg_ui, attr):
                        delattr(self.qeeg_ui, attr)

                # 断开所有信号连接
                try:
                    self.qeeg_ui.thread_run.signal.disconnect()
                except:
                    pass

                # 删除UI对象
                self.qeeg_ui.deleteLater()
                self.qeeg_ui = None

            # # 关闭并删除窗口
            if self.qeeg_window is not None:
                self.qeeg_window.close()
                self.qeeg_window = None

            # 强制多次垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 打印内存使用情况
            import psutil
            process = psutil.Process()
            QLLogging.log.info(
                f"Memory usage after closing qeeg: {process.memory_info().rss / 1024 / 1024:.2f} MB")

        except Exception as e:
            QLLogging.log.exception(f"Error during qeeg cleanup: {str(e)}")
            import traceback
            traceback.print_exc()
        finally:
            if event:
                event.accept()

