    def welcomeDragEnter(self, event):
        """拖拽进入时的样式判断"""
        QLLogging.log.debug("enter welcomeDragEnter")
        try:
            if event.mimeData().hasUrls():
                # 校验所有拖拽项是否为有效文件（非目录）
                if all(self._is_valid_file(url) for url in event.mimeData().urls()):
                    self.welcome_widget.welcome_text1.hide()
                    self.welcome_widget.welcome_widget_old.hide()
                    self.welcome_widget.bottom_label.hide()
                    self.welcome_widget.welcome_text0.setStyleSheet("""
                    QTextEdit {
                        border: 2px solid #2b6cb0;  /* 蓝色高亮边框 */
                        border-radius: 6px;
                        background-color: #ebf5ff;       /* 浅蓝背景 */
                        padding: 14px;             /* 补偿边框加粗 */
                        font-size: 14px;
                        color: #333;
                        border-style: dashed;      /* 可选虚线样式 */
                    }
                    """)

                    # Drag and drop your file here
                    # File supported: EDF, BDF
                    image_word = """
                    <center>
                        <br><br><br><br><br><br><br><br><br><br><br><br>
                        <img src="./resource/picture/Frame.png" width="50" height="50">
                        <div style='font-family:Microsoft YaHei;font-weight:500;font-size:18px;line-height:21px;text-transform:none;text-align:center;color:#000000;justify-content: center'>Drag and drop your file here</div>
                        <div style='font-family:Microsoft YaHei;font-weight:400;font-size:14px;line-height:16px;text-transform:none;text-align:center;color:#979797;justify-content: center'>File supported: EDF, BDF</div>
                    </center>
                    """

                    self.welcome_widget.welcome_text0.setHtml(image_word)
                    self.welcome_widget.update()
                    QLLogging.log.debug("welcomeDragEnter successfully")
                    event.acceptProposedAction()
                    return
            else:
                event.ignore()  # 无效拖拽，保持常态
        except Exception as e:
            QLLogging.log.debug(f"welcomeDragEnter error: {str(e)}")

